/*
 * Autoino 자동 생성 스케치
 * 프로젝트 : uno-all
 * 보드     : 보드 1 · Arduino Uno R3 (arduino-avr 코어)
 * 생성 시각: 2026-01-01T00:00:00+00:00
 *
 * 핀 배정 (Autoino 배선 기준)
 *   LED 1 · 애노드 (+) → D5 — 직렬 저항 330 Ω
 *   LED 2 · 애노드 (+) → D6 — 직렬 저항 330 Ω
 *   푸시 버튼 1 · 2A → D4 — 누르면 LOW
 *   HC-SR04 초음파 센서 1 · Trig → D7
 *   HC-SR04 초음파 센서 1 · Echo → D8
 *   SG90 서보 모터 1 · Signal (주황) → D2
 *   I²C LCD 1602 1 · SDA → A4 (I²C SDA, Wire 가 사용)
 *   I²C LCD 1602 1 · SCL → A5 (I²C SCL, Wire 가 사용)
 *
 * 필요한 라이브러리
 *   - Servo: Arduino IDE 기본 포함 (라이브러리 관리자: Servo)
 *   - Wire: 보드 코어에 포함
 *   - LiquidCrystal_I2C: 라이브러리 관리자에서 'LiquidCrystal I2C' (Frank de Brabander) 설치
 *
 * 이 코드는 배선을 확인하기 위한 동작 예시입니다. 실제 제품·라이브러리 버전에 맞게 확인하세요.
 */

#include <Servo.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// ---------- 핀 · 전역 변수 ----------
const uint8_t LED1_PIN = 5;  // LED 1 · 애노드 (+) → D5 — 직렬 저항 330 Ω
bool led1State = false;
unsigned long timer_led1 = 0;
const uint8_t LED2_PIN = 6;  // LED 2 · 애노드 (+) → D6 — 직렬 저항 330 Ω
bool led2State = false;
unsigned long timer_led2 = 0;
const uint8_t BUTTON1_PIN = 4;  // 푸시 버튼 1 · 2A → D4 — 누르면 LOW
bool button1Last = HIGH;
unsigned long timer_button1 = 0;
const uint8_t SONAR1_TRIG = 7;  // HC-SR04 초음파 센서 1 · Trig → D7
const uint8_t SONAR1_ECHO = 8;  // HC-SR04 초음파 센서 1 · Echo → D8
unsigned long timer_sonar1 = 0;
float sonar1Cm = -1;
const uint8_t SERVO1_PIN = 2;  // SG90 서보 모터 1 · Signal (주황) → D2
Servo servo1;
unsigned long timer_servo1 = 0;
int servo1Angle = 0, servo1Step = 2;
LiquidCrystal_I2C lcd1(0x27, 16, 2);  // 주소는 제품에 따라 0x27 또는 0x3F
unsigned long timer_lcd1 = 0;

// 간격(ms)마다 한 번 true 를 돌려주는 비차단 타이머
bool every(unsigned long &last, unsigned long intervalMs) {
  unsigned long now = millis();
  if (now - last < intervalMs) return false;
  last = now;
  return true;
}

// HC-SR04 거리 측정 (cm). 응답이 없으면 -1
float readDistanceCm(uint8_t trigPin, uint8_t echoPin) {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);
  unsigned long us = pulseIn(echoPin, HIGH, 30000UL);  // 최대 약 5 m
  return us == 0 ? -1.0f : us / 58.0f;
}

void setup() {
  Serial.begin(115200);
  pinMode(LED1_PIN, OUTPUT);
  pinMode(LED2_PIN, OUTPUT);
  pinMode(BUTTON1_PIN, INPUT_PULLUP);
  pinMode(SONAR1_TRIG, OUTPUT);
  pinMode(SONAR1_ECHO, INPUT);
  servo1.attach(SERVO1_PIN);
  Wire.begin();
  lcd1.init();
  lcd1.backlight();
  lcd1.setCursor(0, 0);
  lcd1.print("Autoino");
  Serial.println("Autoino: autoino_board_1.ino start");
}

void loop() {
  // LED 1: 0.5초마다 깜박임
  if (every(timer_led1, 500)) { led1State = !led1State; digitalWrite(LED1_PIN, led1State ? HIGH : LOW); }
  // LED 2: 0.5초마다 깜박임
  if (every(timer_led2, 500)) { led2State = !led2State; digitalWrite(LED2_PIN, led2State ? HIGH : LOW); }
  // 푸시 버튼 1: 20 ms 간격으로 읽어 눌림을 감지 (간단한 디바운스)
  if (every(timer_button1, 20)) {
    bool now = digitalRead(BUTTON1_PIN);
    if (now != button1Last) { button1Last = now; Serial.println(now == LOW ? "button1: pressed" : "button1: released"); }
  }
  // HC-SR04 초음파 센서 1: 0.2초마다 거리 측정
  if (every(timer_sonar1, 200)) { sonar1Cm = readDistanceCm(SONAR1_TRIG, SONAR1_ECHO); Serial.print("sonar1 cm: "); Serial.println(sonar1Cm); }
  // SG90 서보 모터 1: 0°–180° 왕복
  if (every(timer_servo1, 20)) {
    servo1Angle += servo1Step;
    if (servo1Angle <= 0 || servo1Angle >= 180) servo1Step = -servo1Step;
    servo1.write(servo1Angle);
  }
  // I²C LCD 1602 1: 0.5초마다 두 번째 줄 갱신
  if (every(timer_lcd1, 500)) {
    lcd1.setCursor(0, 1);
    lcd1.print("dist "); lcd1.print(sonar1Cm, 1); lcd1.print(" cm   ");
  }
}

