/*
 * Autoino 자동 생성 스케치
 * 프로젝트 : multi-uart-shifter
 * 보드     : 보드 1 · Arduino Uno R3 (arduino-avr 코어)
 * 생성 시각: 2026-01-01T00:00:00+00:00
 *
 * 핀 배정 (Autoino 배선 기준)
 *   LED 1 · 애노드 (+) → D5 — 직렬 저항 330 Ω
 *
 * 필요한 라이브러리
 *   - SoftwareSerial: AVR 보드 코어에 포함
 *
 * 이 코드는 배선을 확인하기 위한 동작 예시입니다. 실제 제품·라이브러리 버전에 맞게 확인하세요.
 */

#include <SoftwareSerial.h>

// ---------- 핀 · 전역 변수 ----------
const uint8_t LED1_PIN = 5;  // LED 1 · 애노드 (+) → D5 — 직렬 저항 330 Ω
bool led1State = false;
unsigned long timer_led1 = 0;
SoftwareSerial link1(4, 7);  // 보드 2 와 UART (RX, TX)
unsigned long timer_link1 = 0;
unsigned long count_link1 = 0;

// 간격(ms)마다 한 번 true 를 돌려주는 비차단 타이머
bool every(unsigned long &last, unsigned long intervalMs) {
  unsigned long now = millis();
  if (now - last < intervalMs) return false;
  last = now;
  return true;
}

void setup() {
  Serial.begin(115200);
  pinMode(LED1_PIN, OUTPUT);
  link1.begin(115200);
  Serial.println("Autoino: autoino_board_1.ino start");
}

void loop() {
  // LED 1: 0.5초마다 깜박임
  if (every(timer_led1, 500)) { led1State = !led1State; digitalWrite(LED1_PIN, led1State ? HIGH : LOW); }
  // UART 통신: 1초마다 보내고, 받은 줄은 시리얼 모니터에 출력
  if (every(timer_link1, 1000)) { link1.print("hello from board-1 #"); link1.println(count_link1++); }
  while (link1.available()) Serial.write(link1.read());
}

/*
 * Autoino 자동 생성 스케치
 * 프로젝트 : multi-uart-shifter
 * 보드     : 보드 2 · ESP32 DevKit V1 (arduino-esp32 코어)
 * 생성 시각: 2026-01-01T00:00:00+00:00
 *
 * 핀 배정 (Autoino 배선 기준)
 *   LED 2 · 애노드 (+) → GPIO32 — 직렬 저항 150 Ω
 *   푸시 버튼 1 · 2A → GPIO33 — 누르면 LOW
 *
 * 필요한 라이브러리
