#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// ---------- 핀 · 전역 변수 ----------
LiquidCrystal_I2C lcd1(0x27, 16, 2);  // 주소는 제품에 따라 0x27 또는 0x3F
unsigned long timer_lcd1 = 0;
const uint8_t LINK1_ADDRESS = 0x27;  // 보드 2 (I²C 주변장치)
unsigned long timer_link1 = 0;
uint8_t count_link1 = 0;

// 간격(ms)마다 한 번 true 를 돌려주는 비차단 타이머
bool every(unsigned long &last, unsigned long intervalMs) {
  unsigned long now = millis();
  if (now - last < intervalMs) return false;
  last = now;
  return true;
}

void setup() {
  Serial.begin(115200);
  Wire.begin();
  lcd1.init();
  lcd1.backlight();
  lcd1.setCursor(0, 0);
  lcd1.print("Autoino");
  Serial.println("Autoino: autoino_board_1.ino start");
}

void loop() {
  // I²C LCD 1602 1: 0.5초마다 두 번째 줄 갱신
  if (every(timer_lcd1, 500)) {
    lcd1.setCursor(0, 1);
    lcd1.print("up "); lcd1.print(millis() / 1000); lcd1.print(" s   ");
  }
  // I²C 통신: 1초마다 주변장치(보드 2)로 1바이트 전송
  if (every(timer_link1, 1000)) {
    Wire.beginTransmission(LINK1_ADDRESS);
    Wire.write(count_link1++);
    if (Wire.endTransmission() != 0) Serial.println("link1: no ACK");
  }
}

