 */

#include <SPI.h>

// ---------- 핀 · 전역 변수 ----------
const uint8_t LINK1_SS = 53;  // 보드 2 (SPI 주변장치) 선택 핀
unsigned long timer_link1 = 0;
uint8_t count_link1 = 0;

// 간격(ms)마다 한 번 true 를 돌려주는 비차단 타이머
bool every(unsigned long &last, unsigned long intervalMs) {
  unsigned long now = millis();
  if (now - last < intervalMs) return false;
  last = now;
  return true;
}

void setup() {
  Serial.begin(115200);
  SPI.begin();
  pinMode(LINK1_SS, OUTPUT);
  digitalWrite(LINK1_SS, HIGH);
  Serial.println("Autoino: autoino_board_1.ino start");
}

void loop() {
  // SPI 통신: 1초마다 1바이트 주고받기
  if (every(timer_link1, 1000)) {
    SPI.beginTransaction(SPISettings(1000000, MSBFIRST, SPI_MODE0));
    digitalWrite(LINK1_SS, LOW);
    uint8_t reply = SPI.transfer(count_link1++);
    digitalWrite(LINK1_SS, HIGH);
    SPI.endTransaction();
    Serial.print("link1 reply: "); Serial.println(reply);
  }
}

