 *
 * 핀 배정 (Autoino 배선 기준)
 *   SG90 서보 모터 1 · Signal (주황) → D4
 *   LED 1 · 애노드 (+) → D5 — 직렬 저항 330 Ω
 *
 * 필요한 라이브러리
 *   - Servo: Arduino IDE 기본 포함 (라이브러리 관리자: Servo)
 *   - SPI: 보드 코어에 포함
 *
 * 이 코드는 배선을 확인하기 위한 동작 예시입니다. 실제 제품·라이브러리 버전에 맞게 확인하세요.
 */

#include <Servo.h>
#include <SPI.h>

// ---------- 핀 · 전역 변수 ----------
const uint8_t SERVO1_PIN = 4;  // SG90 서보 모터 1 · Signal (주황) → D4
Servo servo1;
unsigned long timer_servo1 = 0;
int servo1Angle = 0, servo1Step = 2;
const uint8_t LED1_PIN = 5;  // LED 1 · 애노드 (+) → D5 — 직렬 저항 330 Ω
bool led1State = false;
unsigned long timer_led1 = 0;
volatile uint8_t spiReceived_link1 = 0;
volatile bool spiNew_link1 = false;

// 간격(ms)마다 한 번 true 를 돌려주는 비차단 타이머
bool every(unsigned long &last, unsigned long intervalMs) {
  unsigned long now = millis();
  if (now - last < intervalMs) return false;
  last = now;
  return true;
}

// SPI 주변장치: 보드 1(컨트롤러)가 보낸 바이트를 받고, 받은 값+1 을 다음 응답으로 준비
ISR(SPI_STC_vect) {
  spiReceived_link1 = SPDR;
  SPDR = spiReceived_link1 + 1;
  spiNew_link1 = true;
}

void setup() {
  Serial.begin(115200);
  servo1.attach(SERVO1_PIN);
  pinMode(LED1_PIN, OUTPUT);
  pinMode(MISO, OUTPUT);  // SPI 주변장치: MISO 만 출력
  SPCR |= _BV(SPE);   // SPI 사용 (주변장치 모드)
  SPCR |= _BV(SPIE);  // SPI 인터럽트 사용
  Serial.println("Autoino: autoino_board_2.ino start");
}

void loop() {
  // SG90 서보 모터 1: 0°–180° 왕복
  if (every(timer_servo1, 20)) {
    servo1Angle += servo1Step;
    if (servo1Angle <= 0 || servo1Angle >= 180) servo1Step = -servo1Step;
    servo1.write(servo1Angle);
  }
  // LED 1: 0.5초마다 깜박임
  if (every(timer_led1, 500)) { led1State = !led1State; digitalWrite(LED1_PIN, led1State ? HIGH : LOW); }
  // SPI 통신: 새로 받은 값 출력
  if (spiNew_link1) { spiNew_link1 = false; Serial.print("link1 got: "); Serial.println(spiReceived_link1); }
}

