void setup() {
  Serial.begin(115200);
  pinMode(STEPPER1_STEP, OUTPUT);
  pinMode(STEPPER1_DIR, OUTPUT);
  for (uint8_t i = 0; i < 4; i++) pinMode(stepper1_Pins[i], OUTPUT);
  pinMode(STEPPER1___STEP, OUTPUT);
  pinMode(STEPPER1___DIR, OUTPUT);
  esc1.attach(ESC1_PIN, 1000, 2000);
  esc1.writeMicroseconds(1000);  // 시동: 스로틀 최소 신호
  Serial.println("Autoino: autoino_board_1.ino start");
}

void loop() {
  // A4988 스테퍼 드라이버 1: 200 스텝마다 방향 전환 (풀스텝이면 한 바퀴)
  if (every(timer_stepper1, 2)) {
    digitalWrite(STEPPER1_DIR, forward_stepper1 ? HIGH : LOW);
    digitalWrite(STEPPER1_STEP, HIGH);
    delayMicroseconds(5);
    digitalWrite(STEPPER1_STEP, LOW);
    if (++count_stepper1 >= 200) { count_stepper1 = 0; forward_stepper1 = !forward_stepper1; }
  }
  // ULN2003 스테퍼 드라이버 1: 3 ms 마다 한 스텝
  if (every(timer_stepper1_, 3)) stepCoils(stepper1_Pins, phase_stepper1_);
  // DRV8825 스테퍼 드라이버 1: 200 스텝마다 방향 전환 (풀스텝이면 한 바퀴)
  if (every(timer_stepper1__, 2)) {
    digitalWrite(STEPPER1___DIR, forward_stepper1__ ? HIGH : LOW);
    digitalWrite(STEPPER1___STEP, HIGH);
    delayMicroseconds(5);
    digitalWrite(STEPPER1___STEP, LOW);
    if (++count_stepper1__ >= 200) { count_stepper1__ = 0; forward_stepper1__ = !forward_stepper1__; }
  }
  // ESC 30 A (BLDC 드라이버) 1: 스로틀 신호 유지 (예시는 정지 상태로 둡니다)
  if (every(timer_esc1, 20)) esc1.writeMicroseconds(esc1Throttle);
}

/*
