#include <Adafruit_NeoPixel.h>
#include <DHT.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <TM1637Display.h>
#include <SoftwareSerial.h>
#include <SPI.h>
#include <MFRC522.h>

// ---------- 핀 · 전역 변수 ----------
const uint8_t BUZZER1_PIN = 22;  // 능동 부저 모듈 1 · SIG → D22
bool buzzer1On = false;
unsigned long timer_buzzer1 = 0;
const uint8_t STRIP1_PIN = 23;  // WS2812B LED 스트립 1 · DIN → D23
Adafruit_NeoPixel strip1(30, STRIP1_PIN, NEO_GRB + NEO_KHZ800);
unsigned long timer_strip1 = 0;
uint16_t index_strip1 = 0;
const uint8_t POT1_PIN = A0;  // 가변저항 10 kΩ 1 · OUT → A0
unsigned long timer_pot1 = 0;
const uint8_t STICK1_X = A1;  // 조이스틱 모듈 1 · VRx → A1
const uint8_t STICK1_Y = A2;  // 조이스틱 모듈 1 · VRy → A2
const uint8_t STICK1_SW = 24;  // 조이스틱 모듈 1 · SW → D24 — 누르면 LOW
unsigned long timer_stick1 = 0;
const uint8_t ENCODER1_CLK = 25;  // 로터리 엔코더 1 · CLK → D25
const uint8_t ENCODER1_DT = 26;  // 로터리 엔코더 1 · DT → D26
const uint8_t ENCODER1_SW = 27;  // 로터리 엔코더 1 · SW → D27 — 누르면 LOW
int encoder1Last = HIGH;
long encoder1Value = 0;
const uint8_t DHT1_PIN = 28;  // DHT 온습도 센서 1 · DATA → D28
DHT dht1(DHT1_PIN, DHT11);
unsigned long timer_dht1 = 0;
const uint8_t PIR1_PIN = 29;  // PIR 인체 감지 센서 1 · OUT → D29
bool pir1Last = LOW;
unsigned long timer_pir1 = 0;
const uint8_t LIGHT1_PIN = A3;  // 조도 센서 모듈 1 · AO → A3
unsigned long timer_light1 = 0;
const uint8_t SOIL1_PIN = A4;  // 토양 수분 센서 1 · AO → A4
unsigned long timer_soil1 = 0;
const uint8_t GAS1_PIN = A5;  // MQ-2 가스 센서 1 · AO → A5
unsigned long timer_gas1 = 0;
unsigned long timer_imu1 = 0;
const uint8_t IMU1_ADDRESS = 0x68;
const uint8_t LINE1_PIN = 30;  // 라인 트레이서 센서 1 · DO → D30
bool line1Last = LOW;
unsigned long timer_line1 = 0;
unsigned long timer_oled1 = 0;
Adafruit_SSD1306 oled1(128, 64, &Wire, -1);
const uint8_t SEG1_CLK = 31;  // 7세그먼트 4자리 (TM1637) 1 · CLK → D31
const uint8_t SEG1_DIO = 32;  // 7세그먼트 4자리 (TM1637) 1 · DIO → D32
TM1637Display seg1(SEG1_CLK, SEG1_DIO);
unsigned long timer_seg1 = 0;
const uint8_t BT1_RX = 33;  // HC-05 블루투스 1 · TXD → D33 (보드 입력)
const uint8_t BT1_TX = 34;  // HC-05 블루투스 1 · RXD → D34 (보드 출력)
SoftwareSerial bt1(BT1_RX, BT1_TX);
unsigned long timer_bt1 = 0;
const uint8_t RFID1_SS = 53;  // RC522 RFID 리더 1 · SDA → D53
const uint8_t RFID1_RST = 35;  // RC522 RFID 리더 1 · RST → D35
MFRC522 rfid1(RFID1_SS, RFID1_RST);
unsigned long timer_rfid1 = 0;
const uint8_t RELAY1_PIN = 36;  // 릴레이 모듈 (1채널) 1 · IN → D36 — LOW 에서 켜짐
bool relay1On = false;
unsigned long timer_relay1 = 0;

// 간격(ms)마다 한 번 true 를 돌려주는 비차단 타이머
bool every(unsigned long &last, unsigned long intervalMs) {
  unsigned long now = millis();
  if (now - last < intervalMs) return false;
  last = now;
  return true;
}

// MPU-6050 레지스터에서 16비트 값 읽기
int readImuWord(uint8_t address, uint8_t reg) {
  Wire.beginTransmission(address);
  Wire.write(reg);
  Wire.endTransmission(false);
  Wire.requestFrom(address, (uint8_t)2);
  int high = Wire.read();
  return (high << 8) | Wire.read();
}

void setup() {
  Serial.begin(115200);
  pinMode(BUZZER1_PIN, OUTPUT);
  digitalWrite(BUZZER1_PIN, LOW);
  strip1.begin();
  strip1.setBrightness(40);  // 밝기를 낮춰 전류를 줄인다
  pinMode(STICK1_SW, INPUT_PULLUP);
  pinMode(ENCODER1_CLK, INPUT);
  pinMode(ENCODER1_DT, INPUT);
  pinMode(ENCODER1_SW, INPUT_PULLUP);
  encoder1Last = digitalRead(ENCODER1_CLK);
  dht1.begin();
  pinMode(PIR1_PIN, INPUT);
  Wire.begin();
  Wire.beginTransmission(IMU1_ADDRESS);
  Wire.write(0x6B);  // PWR_MGMT_1
  Wire.write(0);     // 절전 해제
  Wire.endTransmission();
  pinMode(LINE1_PIN, INPUT);
  if (!oled1.begin(SSD1306_SWITCHCAPVCC, 0x3C)) Serial.println("oled1: not found");
  seg1.setBrightness(3);
  bt1.begin(9600);
  SPI.begin();
  rfid1.PCD_Init();
  pinMode(RELAY1_PIN, OUTPUT);
  digitalWrite(RELAY1_PIN, HIGH);
  Serial.println("Autoino: autoino_board_1.ino start");
}

void loop() {
  // 능동 부저 모듈 1: 1초마다 켜기·끄기
  if (every(timer_buzzer1, 1000)) { buzzer1On = !buzzer1On; digitalWrite(BUZZER1_PIN, buzzer1On ? HIGH : LOW); }
  // WS2812B LED 스트립 1: 파란 점 하나가 흐른다
  if (every(timer_strip1, 100)) {
    strip1.clear();
    strip1.setPixelColor(index_strip1, strip1.Color(0, 0, 255));
    strip1.show();
    index_strip1 = (index_strip1 + 1) % 30;
  }
  // 가변저항 10 kΩ 1: 0.5초마다 아날로그 값 출력
  if (every(timer_pot1, 500)) { Serial.print("pot1: "); Serial.println(analogRead(POT1_PIN)); }
  // 조이스틱 모듈 1: 0.2초마다 축 값과 버튼 출력
  if (every(timer_stick1, 200)) {
    Serial.print("stick1 x="); Serial.print(analogRead(STICK1_X));
    Serial.print(" y="); Serial.print(analogRead(STICK1_Y));
    Serial.print(" sw="); Serial.println(digitalRead(STICK1_SW) == LOW ? "down" : "up");
  }
  // 로터리 엔코더 1: CLK 가 바뀔 때 DT 로 방향을 판단
  { int now = digitalRead(ENCODER1_CLK);
    if (now != encoder1Last) {
      encoder1Last = now;
      if (now == LOW) { encoder1Value += digitalRead(ENCODER1_DT) != now ? 1 : -1; Serial.print("encoder1: "); Serial.println(encoder1Value); }
    }
  }
  // DHT 온습도 센서 1: 2초마다 온도·습도 출력
  if (every(timer_dht1, 2000)) {
    Serial.print("dht1 C="); Serial.print(dht1.readTemperature());
    Serial.print(" %="); Serial.println(dht1.readHumidity());
  }
  // PIR 인체 감지 센서 1: 값이 바뀌면 출력
  if (every(timer_pir1, 50)) {
    bool now = digitalRead(PIR1_PIN);
    if (now != pir1Last) { pir1Last = now; Serial.print("pir1: "); Serial.println(now == HIGH ? "HIGH" : "LOW"); }
  }
  // 조도 센서 모듈 1: 0.5초마다 아날로그 값 출력
  if (every(timer_light1, 500)) { Serial.print("light1: "); Serial.println(analogRead(LIGHT1_PIN)); }
  // 토양 수분 센서 1: 0.5초마다 아날로그 값 출력
  if (every(timer_soil1, 500)) { Serial.print("soil1: "); Serial.println(analogRead(SOIL1_PIN)); }
  // MQ-2 가스 센서 1: 0.5초마다 아날로그 값 출력
  if (every(timer_gas1, 500)) { Serial.print("gas1: "); Serial.println(analogRead(GAS1_PIN)); }
  // MPU-6050 가속도·자이로 1: 0.2초마다 가속도 X·Y·Z 출력
  if (every(timer_imu1, 200)) {
    Serial.print("imu1 ax="); Serial.print(readImuWord(IMU1_ADDRESS, 0x3B));
    Serial.print(" ay="); Serial.print(readImuWord(IMU1_ADDRESS, 0x3D));
    Serial.print(" az="); Serial.println(readImuWord(IMU1_ADDRESS, 0x3F));
  }
  // 라인 트레이서 센서 1: 값이 바뀌면 출력
  if (every(timer_line1, 50)) {
    bool now = digitalRead(LINE1_PIN);
    if (now != line1Last) { line1Last = now; Serial.print("line1: "); Serial.println(now == HIGH ? "HIGH" : "LOW"); }
  }
  // OLED 0.96인치 (SSD1306) 1: 0.5초마다 경과 시간 표시
  if (every(timer_oled1, 500)) {
    oled1.clearDisplay();
    oled1.setTextSize(2);
    oled1.setTextColor(SSD1306_WHITE);
    oled1.setCursor(0, 0);
    oled1.println("Autoino");
    oled1.println(millis() / 1000);
    oled1.display();
  }
  // 7세그먼트 4자리 (TM1637) 1: 1초마다 경과 시간 표시
  if (every(timer_seg1, 1000)) seg1.showNumberDec((millis() / 1000) % 10000);
  // HC-05 블루투스 1: 받은 데이터를 시리얼 모니터로 출력하고 2초마다 인사
  while (bt1.available()) Serial.write(bt1.read());
  if (every(timer_bt1, 2000)) bt1.println("hello from Autoino");
  // RC522 RFID 리더 1: 카드가 닿으면 UID 출력
  if (every(timer_rfid1, 200) && rfid1.PICC_IsNewCardPresent() && rfid1.PICC_ReadCardSerial()) {
    Serial.print("rfid1 UID:");
    for (byte i = 0; i < rfid1.uid.size; i++) { Serial.print(' '); Serial.print(rfid1.uid.uidByte[i], HEX); }
    Serial.println();
    rfid1.PICC_HaltA();
  }
  // 릴레이 모듈 (1채널) 1: 1초마다 켜기·끄기
  if (every(timer_relay1, 1000)) { relay1On = !relay1On; digitalWrite(RELAY1_PIN, relay1On ? LOW : HIGH); }
}

/*
 * Autoino 자동 생성 스케치
 * 프로젝트 : catalog-esp32
 * 보드     : 보드 1 · ESP32 DevKit V1 (arduino-esp32 코어)
 * 생성 시각: 2026-01-01T00:00:00+00:00
 *
 * 핀 배정 (Autoino 배선 기준)
 *   가변저항 10 kΩ 1 · OUT → GPIO36
 *   DHT 온습도 센서 1 · DATA → GPIO27
 *   MQ-2 가스 센서 1 · AO → GPIO39
 *   MPU-6050 가속도·자이로 1 · SDA → GPIO21 (I²C SDA, Wire 가 사용)
 *   MPU-6050 가속도·자이로 1 · SCL → GPIO22 (I²C SCL, Wire 가 사용)
 *   OLED 0.96인치 (SSD1306) 1 · SDA → GPIO21 (I²C SDA, Wire 가 사용)
 *   OLED 0.96인치 (SSD1306) 1 · SCL → GPIO22 (I²C SCL, Wire 가 사용)
 *   HC-05 블루투스 1 · TXD → GPIO34 (보드 입력)
 *   HC-05 블루투스 1 · RXD → GPIO17 (보드 출력)
 *   RC522 RFID 리더 1 · SDA → GPIO32
 *   RC522 RFID 리더 1 · RST → GPIO16
 *   RC522 RFID 리더 1 · SCK → GPIO18
 *   RC522 RFID 리더 1 · MOSI → GPIO23
 *   RC522 RFID 리더 1 · MISO → GPIO19
 *   TB6612FNG 모터 드라이버 1 · STBY → GPIO4
 *   TB6612FNG 모터 드라이버 1 · PWMA → GPIO33
 *   TB6612FNG 모터 드라이버 1 · AIN1 → GPIO25
 *   TB6612FNG 모터 드라이버 1 · AIN2 → GPIO26
 *
 * 필요한 라이브러리
 *   - DHT sensor library: 라이브러리 관리자에서 'DHT sensor library' (Adafruit) 설치
 *   - Wire: 보드 코어에 포함
 *   - Adafruit SSD1306: 라이브러리 관리자에서 'Adafruit SSD1306' 설치 (Adafruit GFX 함께 설치)
 *   - SPI: 보드 코어에 포함
 *   - MFRC522: 라이브러리 관리자에서 'MFRC522' 설치
 *
 * 이 코드는 배선을 확인하기 위한 동작 예시입니다. 실제 제품·라이브러리 버전에 맞게 확인하세요.
 * 주의: 검사 오류 1건이 있는 상태에서 생성했습니다. [검사] 탭을 먼저 확인하세요.
 */

#include <DHT.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <SPI.h>
#include <MFRC522.h>

// ---------- 핀 · 전역 변수 ----------
const uint8_t POT1_PIN = 36;  // 가변저항 10 kΩ 1 · OUT → GPIO36
unsigned long timer_pot1 = 0;
const uint8_t DHT1_PIN = 27;  // DHT 온습도 센서 1 · DATA → GPIO27
DHT dht1(DHT1_PIN, DHT11);
unsigned long timer_dht1 = 0;
const uint8_t GAS1_PIN = 39;  // MQ-2 가스 센서 1 · AO → GPIO39
unsigned long timer_gas1 = 0;
unsigned long timer_imu1 = 0;
const uint8_t IMU1_ADDRESS = 0x68;
unsigned long timer_oled1 = 0;
Adafruit_SSD1306 oled1(128, 64, &Wire, -1);
const uint8_t BT1_RX = 34;  // HC-05 블루투스 1 · TXD → GPIO34 (보드 입력)
const uint8_t BT1_TX = 17;  // HC-05 블루투스 1 · RXD → GPIO17 (보드 출력)
unsigned long timer_bt1 = 0;
const uint8_t RFID1_SS = 32;  // RC522 RFID 리더 1 · SDA → GPIO32
const uint8_t RFID1_RST = 16;  // RC522 RFID 리더 1 · RST → GPIO16
const uint8_t RFID1_SCK = 18;  // RC522 RFID 리더 1 · SCK → GPIO18
const uint8_t RFID1_MOSI = 23;  // RC522 RFID 리더 1 · MOSI → GPIO23
const uint8_t RFID1_MISO = 19;  // RC522 RFID 리더 1 · MISO → GPIO19
MFRC522 rfid1(RFID1_SS, RFID1_RST);
unsigned long timer_rfid1 = 0;
const uint8_t MOTOR1_STBY = 4;  // TB6612FNG 모터 드라이버 1 · STBY → GPIO4
const uint8_t MOTOR1A_EN = 33;  // TB6612FNG 모터 드라이버 1 · PWMA → GPIO33
const uint8_t MOTOR1A_IN1 = 25;  // TB6612FNG 모터 드라이버 1 · AIN1 → GPIO25
const uint8_t MOTOR1A_IN2 = 26;  // TB6612FNG 모터 드라이버 1 · AIN2 → GPIO26
unsigned long timer_motor1a = 0;
uint8_t state_motor1a = 0;
// TT 기어드 모터 1: 모터 드라이버 코드에서 제어합니다.

// 간격(ms)마다 한 번 true 를 돌려주는 비차단 타이머
bool every(unsigned long &last, unsigned long intervalMs) {
  unsigned long now = millis();
  if (now - last < intervalMs) return false;
  last = now;
  return true;
}

// MPU-6050 레지스터에서 16비트 값 읽기
int readImuWord(uint8_t address, uint8_t reg) {
  Wire.beginTransmission(address);
  Wire.write(reg);
  Wire.endTransmission(false);
  Wire.requestFrom(address, (uint8_t)2);
  int high = Wire.read();
  return (high << 8) | Wire.read();
}

// H 브리지 모터 구동: speed -255(역방향) … 255(정방향)
void driveMotor(uint8_t in1, uint8_t in2, uint8_t en, int speed) {
  digitalWrite(in1, speed > 0 ? HIGH : LOW);
  digitalWrite(in2, speed < 0 ? HIGH : LOW);
  analogWrite(en, speed < 0 ? -speed : speed);
}

void setup() {
  Serial.begin(115200);
  dht1.begin();
  Wire.begin(21, 22);  // SDA, SCL
  Wire.beginTransmission(IMU1_ADDRESS);
  Wire.write(0x6B);  // PWR_MGMT_1
  Wire.write(0);     // 절전 해제
  Wire.endTransmission();
  if (!oled1.begin(SSD1306_SWITCHCAPVCC, 0x3C)) Serial.println("oled1: not found");
  Serial2.begin(9600, SERIAL_8N1, BT1_RX, BT1_TX);
  SPI.begin(RFID1_SCK, RFID1_MISO, RFID1_MOSI, RFID1_SS);
  rfid1.PCD_Init();
  pinMode(MOTOR1_STBY, OUTPUT);
  digitalWrite(MOTOR1_STBY, HIGH);  // 대기 해제
  pinMode(MOTOR1A_EN, OUTPUT);
  pinMode(MOTOR1A_IN1, OUTPUT);
  pinMode(MOTOR1A_IN2, OUTPUT);
  Serial.println("Autoino: autoino_board_1.ino start");
}

void loop() {
  // 가변저항 10 kΩ 1: 0.5초마다 아날로그 값 출력
  if (every(timer_pot1, 500)) { Serial.print("pot1: "); Serial.println(analogRead(POT1_PIN)); }
  // DHT 온습도 센서 1: 2초마다 온도·습도 출력
  if (every(timer_dht1, 2000)) {
    Serial.print("dht1 C="); Serial.print(dht1.readTemperature());
    Serial.print(" %="); Serial.println(dht1.readHumidity());
  }
  // MQ-2 가스 센서 1: 0.5초마다 아날로그 값 출력
  if (every(timer_gas1, 500)) { Serial.print("gas1: "); Serial.println(analogRead(GAS1_PIN)); }
  // MPU-6050 가속도·자이로 1: 0.2초마다 가속도 X·Y·Z 출력
  if (every(timer_imu1, 200)) {
    Serial.print("imu1 ax="); Serial.print(readImuWord(IMU1_ADDRESS, 0x3B));
    Serial.print(" ay="); Serial.print(readImuWord(IMU1_ADDRESS, 0x3D));
    Serial.print(" az="); Serial.println(readImuWord(IMU1_ADDRESS, 0x3F));
  }
  // OLED 0.96인치 (SSD1306) 1: 0.5초마다 경과 시간 표시
  if (every(timer_oled1, 500)) {
    oled1.clearDisplay();
    oled1.setTextSize(2);
    oled1.setTextColor(SSD1306_WHITE);
    oled1.setCursor(0, 0);
    oled1.println("Autoino");
    oled1.println(millis() / 1000);
    oled1.display();
  }
  // HC-05 블루투스 1: 받은 데이터를 시리얼 모니터로 출력하고 2초마다 인사
  while (Serial2.available()) Serial.write(Serial2.read());
  if (every(timer_bt1, 2000)) Serial2.println("hello from Autoino");
  // RC522 RFID 리더 1: 카드가 닿으면 UID 출력
  if (every(timer_rfid1, 200) && rfid1.PICC_IsNewCardPresent() && rfid1.PICC_ReadCardSerial()) {
    Serial.print("rfid1 UID:");
    for (byte i = 0; i < rfid1.uid.size; i++) { Serial.print(' '); Serial.print(rfid1.uid.uidByte[i], HEX); }
    Serial.println();
    rfid1.PICC_HaltA();
  }
  // TB6612FNG 모터 드라이버 1 모터 A: 정방향 → 정지 → 역방향 → 정지 (2초 간격)
  if (every(timer_motor1a, 2000)) {
    state_motor1a = (state_motor1a + 1) % 4;
    driveMotor(MOTOR1A_IN1, MOTOR1A_IN2, MOTOR1A_EN, state_motor1a == 1 ? 180 : state_motor1a == 3 ? -180 : 0);
  }
}

/*
 * Autoino 자동 생성 스케치
 * 프로젝트 : route-breadboard
 * 보드     : 보드 1 · Arduino Uno R3 (arduino-avr 코어)
 * 생성 시각: 2026-01-01T00:00:00+00:00
 *
 * 핀 배정 (Autoino 배선 기준)
 *   TB6612FNG 모터 드라이버 1 · STBY → D4
 *   TB6612FNG 모터 드라이버 1 · PWMA → D5
 *   TB6612FNG 모터 드라이버 1 · AIN1 → D7
 *   TB6612FNG 모터 드라이버 1 · AIN2 → D8
 *   LED 1 · 애노드 (+) → D6 — 직렬 저항 330 Ω
 *   HC-SR04 초음파 센서 1 · Trig → D2
 *   HC-SR04 초음파 센서 1 · Echo → D9
 *   SG90 서보 모터 1 · Signal (주황) → D12
 *
 * 필요한 라이브러리
 *   - Servo: Arduino IDE 기본 포함 (라이브러리 관리자: Servo)
 *
 * 이 코드는 배선을 확인하기 위한 동작 예시입니다. 실제 제품·라이브러리 버전에 맞게 확인하세요.
 */

#include <Servo.h>

// ---------- 핀 · 전역 변수 ----------
// 외부 전원 1: 전원 부품이라 별도 코드가 필요 없습니다.
const uint8_t MOTOR1_STBY = 4;  // TB6612FNG 모터 드라이버 1 · STBY → D4
const uint8_t MOTOR1A_EN = 5;  // TB6612FNG 모터 드라이버 1 · PWMA → D5
const uint8_t MOTOR1A_IN1 = 7;  // TB6612FNG 모터 드라이버 1 · AIN1 → D7
const uint8_t MOTOR1A_IN2 = 8;  // TB6612FNG 모터 드라이버 1 · AIN2 → D8
unsigned long timer_motor1a = 0;
uint8_t state_motor1a = 0;
// TT 기어드 모터 1: 모터 드라이버 코드에서 제어합니다.
const uint8_t LED1_PIN = 6;  // LED 1 · 애노드 (+) → D6 — 직렬 저항 330 Ω
bool led1State = false;
unsigned long timer_led1 = 0;
const uint8_t SONAR1_TRIG = 2;  // HC-SR04 초음파 센서 1 · Trig → D2
const uint8_t SONAR1_ECHO = 9;  // HC-SR04 초음파 센서 1 · Echo → D9
unsigned long timer_sonar1 = 0;
float sonar1Cm = -1;
const uint8_t SERVO1_PIN = 12;  // SG90 서보 모터 1 · Signal (주황) → D12
Servo servo1;
unsigned long timer_servo1 = 0;
int servo1Angle = 0, servo1Step = 2;

// 간격(ms)마다 한 번 true 를 돌려주는 비차단 타이머
bool every(unsigned long &last, unsigned long intervalMs) {
  unsigned long now = millis();
  if (now - last < intervalMs) return false;
  last = now;
  return true;
}

// H 브리지 모터 구동: speed -255(역방향) … 255(정방향)
void driveMotor(uint8_t in1, uint8_t in2, uint8_t en, int speed) {
  digitalWrite(in1, speed > 0 ? HIGH : LOW);
  digitalWrite(in2, speed < 0 ? HIGH : LOW);
  analogWrite(en, speed < 0 ? -speed : speed);
}

// HC-SR04 거리 측정 (cm). 응답이 없으면 -1
float readDistanceCm(uint8_t trigPin, uint8_t echoPin) {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);
  unsigned long us = pulseIn(echoPin, HIGH, 30000UL);  // 최대 약 5 m
  return us == 0 ? -1.0f : us / 58.0f;
}

void setup() {
  Serial.begin(115200);
  pinMode(MOTOR1_STBY, OUTPUT);
  digitalWrite(MOTOR1_STBY, HIGH);  // 대기 해제
  pinMode(MOTOR1A_EN, OUTPUT);
  pinMode(MOTOR1A_IN1, OUTPUT);
  pinMode(MOTOR1A_IN2, OUTPUT);
  pinMode(LED1_PIN, OUTPUT);
  pinMode(SONAR1_TRIG, OUTPUT);
  pinMode(SONAR1_ECHO, INPUT);
  servo1.attach(SERVO1_PIN);
  Serial.println("Autoino: autoino_board_1.ino start");
}

void loop() {
  // TB6612FNG 모터 드라이버 1 모터 A: 정방향 → 정지 → 역방향 → 정지 (2초 간격)
  if (every(timer_motor1a, 2000)) {
    state_motor1a = (state_motor1a + 1) % 4;
    driveMotor(MOTOR1A_IN1, MOTOR1A_IN2, MOTOR1A_EN, state_motor1a == 1 ? 180 : state_motor1a == 3 ? -180 : 0);
  }
  // LED 1: 0.5초마다 깜박임
  if (every(timer_led1, 500)) { led1State = !led1State; digitalWrite(LED1_PIN, led1State ? HIGH : LOW); }
  // HC-SR04 초음파 센서 1: 0.2초마다 거리 측정
  if (every(timer_sonar1, 200)) { sonar1Cm = readDistanceCm(SONAR1_TRIG, SONAR1_ECHO); Serial.print("sonar1 cm: "); Serial.println(sonar1Cm); }
  // SG90 서보 모터 1: 0°–180° 왕복
  if (every(timer_servo1, 20)) {
    servo1Angle += servo1Step;
    if (servo1Angle <= 0 || servo1Angle >= 180) servo1Step = -servo1Step;
    servo1.write(servo1Angle);
  }
}

