 *   LED 1 · 애노드 (+) → D5 — 직렬 저항 330 Ω
 *
 * 필요한 라이브러리
 *   - 없음
 *
 * 이 코드는 배선을 확인하기 위한 동작 예시입니다. 실제 제품·라이브러리 버전에 맞게 확인하세요.
 */

// ---------- 핀 · 전역 변수 ----------
// 핀 공유: 푸시 버튼 1, 푸시 버튼 2, 푸시 버튼 3 이(가) A0 을(를) 함께 씁니다 — 저항 사다리 코드에서 함께 읽습니다.
const uint8_t LADDER0_PIN = A0;  // 푸시 버튼 1 · 2A → A0 — 버튼 3개 저항 사다리 (푸시 버튼 1: 저항 없이, 푸시 버튼 2: 4.7 kΩ, 푸시 버튼 3: 22 kΩ)
const int LADDER0_LIMITS[] = {44, 254, 779};  // analogRead 경계: 이 값보다 작으면 그 순서의 버튼
const char* const LADDER0_NAMES[] = {"button1", "button2", "button3"};
int ladder0Last = -1;
unsigned long timer_ladder0 = 0;
// 푸시 버튼 2: 푸시 버튼 1 와(과) 같은 핀(A0)을 함께 씁니다 (핀 공유) — 저항 사다리 코드에서 함께 읽습니다.
// 푸시 버튼 3: 푸시 버튼 1 와(과) 같은 핀(A0)을 함께 씁니다 (핀 공유) — 저항 사다리 코드에서 함께 읽습니다.
const uint8_t LED1_PIN = 5;  // LED 1 · 애노드 (+) → D5 — 직렬 저항 330 Ω
bool led1State = false;
unsigned long timer_led1 = 0;

// 간격(ms)마다 한 번 true 를 돌려주는 비차단 타이머
bool every(unsigned long &last, unsigned long intervalMs) {
  unsigned long now = millis();
  if (now - last < intervalMs) return false;
  last = now;
  return true;
}

void setup() {
  Serial.begin(115200);
  pinMode(LADDER0_PIN, INPUT_PULLUP);  // 내부 풀업(20–50 kΩ)이 사다리의 위쪽 저항 역할을 합니다
  pinMode(LED1_PIN, OUTPUT);
  Serial.println("Autoino: autoino_board_1.ino start");
}

void loop() {
  // 버튼 사다리 A0: 20 ms 마다 읽어 눌린 버튼을 알려 줌 (한 번에 하나만 누르세요)
  if (every(timer_ladder0, 20)) {
    int v = analogRead(LADDER0_PIN);
    int pressed = -1;
    for (int i = 0; i < 3; i++) if (v < LADDER0_LIMITS[i]) { pressed = i; break; }
    if (pressed != ladder0Last) {
      ladder0Last = pressed;
      if (pressed < 0) Serial.println("ladder0: released");
      else { Serial.print(LADDER0_NAMES[pressed]); Serial.println(": pressed"); }
    }
  }
  // LED 1: 0.5초마다 깜박임
  if (every(timer_led1, 500)) { led1State = !led1State; digitalWrite(LED1_PIN, led1State ? HIGH : LOW); }
}

