 * 생성 시각: 2026-01-01T00:00:00+00:00
 *
 * 핀 배정 (Autoino 배선 기준)
 *   PCA9685 16채널 서보 드라이버 1 · SDA → A4 (I²C SDA, Wire 가 사용)
 *   PCA9685 16채널 서보 드라이버 1 · SCL → A5 (I²C SCL, Wire 가 사용)
 *   SG90 서보 모터 1 · 신호 → PCA9685 16채널 서보 드라이버 1 채널 0
 *   MG996R 서보 모터 1 · 신호 → PCA9685 16채널 서보 드라이버 1 채널 1
 *   FS90R 연속 회전 서보 1 · 신호 → PCA9685 16채널 서보 드라이버 1 채널 2
 *
 * 필요한 라이브러리
 *   - Wire: 보드 코어에 포함
 *   - Adafruit PWM Servo Driver Library: 라이브러리 관리자에서 'Adafruit PWM Servo Driver Library' 설치
 *
 * 이 코드는 배선을 확인하기 위한 동작 예시입니다. 실제 제품·라이브러리 버전에 맞게 확인하세요.
 */

#include <Wire.h>
#include <Adafruit_PWMServoDriver.h>

// ---------- 핀 · 전역 변수 ----------
Adafruit_PWMServoDriver servos1(0x40);  // PCA9685 16채널 서보 드라이버 1 (I²C 0x40)
unsigned long timer_servo1 = 0;
int servo1Angle = 0, servo1Step = 2;
unsigned long timer_servo1_ = 0;
int servo1_Angle = 0, servo1_Step = 2;
unsigned long timer_servo1__ = 0;
uint8_t servo1__State = 0;
// SG90 서보 모터 1: PCA9685 16채널 서보 드라이버 1 의 채널 0 에서 제어합니다 (아래 서보 드라이버 코드).
// MG996R 서보 모터 1: PCA9685 16채널 서보 드라이버 1 의 채널 1 에서 제어합니다 (아래 서보 드라이버 코드).
// FS90R 연속 회전 서보 1: PCA9685 16채널 서보 드라이버 1 의 채널 2 에서 제어합니다 (아래 서보 드라이버 코드).
// 외부 전원 1: 전원 부품이라 별도 코드가 필요 없습니다.

// 간격(ms)마다 한 번 true 를 돌려주는 비차단 타이머
bool every(unsigned long &last, unsigned long intervalMs) {
  unsigned long now = millis();
  if (now - last < intervalMs) return false;
  last = now;
  return true;
}

void setup() {
  Serial.begin(115200);
  Wire.begin();
  servos1.begin();
  servos1.setOscillatorFrequency(27000000);
  servos1.setPWMFreq(50);  // 서보 펄스 주기 50 Hz (20 ms)
  servos1.writeMicroseconds(2, 1500);  // FS90R 연속 회전 서보 1: 정지
  Serial.println("Autoino: autoino_board_1.ino start");
}

void loop() {
  // SG90 서보 모터 1 (채널 0): 0°–180° 왕복 (펄스 500–2500 µs)
  if (every(timer_servo1, 20)) {
    servo1Angle += servo1Step;
    if (servo1Angle <= 0 || servo1Angle >= 180) servo1Step = -servo1Step;
    servos1.writeMicroseconds(0, map(servo1Angle, 0, 180, 500, 2500));
  }
  // MG996R 서보 모터 1 (채널 1): 0°–180° 왕복 (펄스 500–2500 µs)
  if (every(timer_servo1_, 20)) {
    servo1_Angle += servo1_Step;
    if (servo1_Angle <= 0 || servo1_Angle >= 180) servo1_Step = -servo1_Step;
    servos1.writeMicroseconds(1, map(servo1_Angle, 0, 180, 500, 2500));
  }
  // FS90R 연속 회전 서보 1 (채널 2): 정방향 → 정지 → 역방향 → 정지 (2초 간격)
  if (every(timer_servo1__, 2000)) {
    servo1__State = (servo1__State + 1) % 4;
    servos1.writeMicroseconds(2, servo1__State == 1 ? 1700 : servo1__State == 3 ? 1300 : 1500);
  }
}

