 *   L298N 모터 드라이버 1 · ENA → D5
 *   L298N 모터 드라이버 1 · IN1 → D4
 *   L298N 모터 드라이버 1 · IN2 → D7
 *   L298N 모터 드라이버 1 · ENB → D5
 *   L298N 모터 드라이버 1 · IN3 → D4
 *   L298N 모터 드라이버 1 · IN4 → D7
 *
 * 필요한 라이브러리
 *   - 없음
 *
 * 이 코드는 배선을 확인하기 위한 동작 예시입니다. 실제 제품·라이브러리 버전에 맞게 확인하세요.
 */

// ---------- 핀 · 전역 변수 ----------
// 외부 전원 1: 전원 부품이라 별도 코드가 필요 없습니다.
// 핀 공유: L298N 모터 드라이버 1 ENA, L298N 모터 드라이버 1 ENB 이(가) D5 을(를) 함께 씁니다 — 같은 신호(모터 속도(EN·PWM))로 같이 움직입니다.
// 핀 공유: L298N 모터 드라이버 1 IN1, L298N 모터 드라이버 1 IN3 이(가) D4 을(를) 함께 씁니다 — 같은 신호(모터 방향(IN))로 같이 움직입니다.
// 핀 공유: L298N 모터 드라이버 1 IN2, L298N 모터 드라이버 1 IN4 이(가) D7 을(를) 함께 씁니다 — 같은 신호(모터 방향(IN))로 같이 움직입니다.
const uint8_t MOTOR1A_EN = 5;  // L298N 모터 드라이버 1 · ENA → D5
const uint8_t MOTOR1A_IN1 = 4;  // L298N 모터 드라이버 1 · IN1 → D4
const uint8_t MOTOR1A_IN2 = 7;  // L298N 모터 드라이버 1 · IN2 → D7
unsigned long timer_motor1a = 0;
uint8_t state_motor1a = 0;
const uint8_t MOTOR1B_EN = 5;  // L298N 모터 드라이버 1 · ENB → D5
const uint8_t MOTOR1B_IN1 = 4;  // L298N 모터 드라이버 1 · IN3 → D4
const uint8_t MOTOR1B_IN2 = 7;  // L298N 모터 드라이버 1 · IN4 → D7
unsigned long timer_motor1b = 0;
uint8_t state_motor1b = 0;
// TT 기어드 모터 1: 모터 드라이버 코드에서 제어합니다.
// TT 기어드 모터 2: 모터 드라이버 코드에서 제어합니다.

// 간격(ms)마다 한 번 true 를 돌려주는 비차단 타이머
bool every(unsigned long &last, unsigned long intervalMs) {
  unsigned long now = millis();
  if (now - last < intervalMs) return false;
  last = now;
  return true;
}

// H 브리지 모터 구동: speed -255(역방향) … 255(정방향)
void driveMotor(uint8_t in1, uint8_t in2, uint8_t en, int speed) {
  digitalWrite(in1, speed > 0 ? HIGH : LOW);
  digitalWrite(in2, speed < 0 ? HIGH : LOW);
  analogWrite(en, speed < 0 ? -speed : speed);
}

void setup() {
  Serial.begin(115200);
  pinMode(MOTOR1A_EN, OUTPUT);
  pinMode(MOTOR1A_IN1, OUTPUT);
  pinMode(MOTOR1A_IN2, OUTPUT);
  pinMode(MOTOR1B_EN, OUTPUT);
  pinMode(MOTOR1B_IN1, OUTPUT);
  pinMode(MOTOR1B_IN2, OUTPUT);
  Serial.println("Autoino: autoino_board_1.ino start");
}

void loop() {
  // L298N 모터 드라이버 1 모터 A: 정방향 → 정지 → 역방향 → 정지 (2초 간격)
  if (every(timer_motor1a, 2000)) {
    state_motor1a = (state_motor1a + 1) % 4;
    driveMotor(MOTOR1A_IN1, MOTOR1A_IN2, MOTOR1A_EN, state_motor1a == 1 ? 180 : state_motor1a == 3 ? -180 : 0);
  }
  // L298N 모터 드라이버 1 모터 B: 정방향 → 정지 → 역방향 → 정지 (2초 간격)
  if (every(timer_motor1b, 2000)) {
    state_motor1b = (state_motor1b + 1) % 4;
    driveMotor(MOTOR1B_IN1, MOTOR1B_IN2, MOTOR1B_EN, state_motor1b == 1 ? 180 : state_motor1b == 3 ? -180 : 0);
  }
}

