const uint8_t SONAR1_TRIG = 7;  // HC-SR04 초음파 센서 1 · Trig → D7
const uint8_t SONAR1_ECHO = 4;  // HC-SR04 초음파 센서 1 · Echo → D4
unsigned long timer_sonar1 = 0;
float sonar1Cm = -1;
