const uint8_t SONAR2_ECHO = 8;  // HC-SR04 초음파 센서 2 · Echo → D8
unsigned long timer_sonar2 = 0;
float sonar2Cm = -1;
// HC-SR04 초음파 센서 3: Trig 핀(D7)을 HC-SR04 초음파 센서 1 와(과) 함께 씁니다 (핀 공유).
const uint8_t SONAR3_TRIG = 7;  // HC-SR04 초음파 센서 3 · Trig → D7
const uint8_t SONAR3_ECHO = 2;  // HC-SR04 초음파 센서 3 · Echo → D2
unsigned long timer_sonar3 = 0;
float sonar3Cm = -1;

// 간격(ms)마다 한 번 true 를 돌려주는 비차단 타이머
bool every(unsigned long &last, unsigned long intervalMs) {
  unsigned long now = millis();
  if (now - last < intervalMs) return false;
  last = now;
  return true;
}

// HC-SR04 거리 측정 (cm). 응답이 없으면 -1
float readDistanceCm(uint8_t trigPin, uint8_t echoPin) {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);
  unsigned long us = pulseIn(echoPin, HIGH, 30000UL);  // 최대 약 5 m
  return us == 0 ? -1.0f : us / 58.0f;
}

void setup() {
  Serial.begin(115200);
  pinMode(SONAR1_TRIG, OUTPUT);
  pinMode(SONAR1_ECHO, INPUT);
  pinMode(SONAR2_TRIG, OUTPUT);
  pinMode(SONAR2_ECHO, INPUT);
  pinMode(SONAR3_TRIG, OUTPUT);
  pinMode(SONAR3_ECHO, INPUT);
  Serial.println("Autoino: autoino_board_1.ino start");
}

void loop() {
  // HC-SR04 초음파 센서 1: 0.2초마다 거리 측정
  if (every(timer_sonar1, 200)) { sonar1Cm = readDistanceCm(SONAR1_TRIG, SONAR1_ECHO); Serial.print("sonar1 cm: "); Serial.println(sonar1Cm); }
  // HC-SR04 초음파 센서 2: 0.2초마다 거리 측정
  if (every(timer_sonar2, 200)) { sonar2Cm = readDistanceCm(SONAR2_TRIG, SONAR2_ECHO); Serial.print("sonar2 cm: "); Serial.println(sonar2Cm); }
  // HC-SR04 초음파 센서 3: 0.2초마다 거리 측정
