}

// 아날로그 멀티플렉서 (16채널) 1: 채널(0–7)을 골라 SIG(A0) 로 읽는다
int readMux1(uint8_t channel) {
  for (uint8_t i = 0; i < 3; i++) digitalWrite(MUX1_SELECT[i], (channel >> i) & 1);
  delayMicroseconds(10);  // 채널을 바꾼 뒤 신호가 자리 잡을 시간
  analogRead(MUX1_SIG);  // 첫 값은 버린다 (ADC 가 새 채널 전압으로 바뀌도록)
  return analogRead(MUX1_SIG);
}

void setup() {
  Serial.begin(115200);
  for (uint8_t i = 0; i < 3; i++) pinMode(MUX1_SELECT[i], OUTPUT);
  pinMode(STICK1_SW, INPUT_PULLUP);
  Serial.println("Autoino: autoino_board_1.ino start");
}

void loop() {
  // 가변저항 10 kΩ 1: 0.5초마다 아날로그 값 출력
  if (every(timer_pot1, 500)) { Serial.print("pot1: "); Serial.println(readMux1(0)); }
  // 조도 센서 모듈 1: 0.5초마다 아날로그 값 출력
  if (every(timer_light1, 500)) { Serial.print("light1: "); Serial.println(readMux1(1)); }
  // 토양 수분 센서 1: 0.5초마다 아날로그 값 출력
  if (every(timer_soil1, 500)) { Serial.print("soil1: "); Serial.println(readMux1(2)); }
  // 조이스틱 모듈 1: 0.2초마다 축 값과 버튼 출력
  if (every(timer_stick1, 200)) {
    Serial.print("stick1 x="); Serial.print(readMux1(3));
    Serial.print(" y="); Serial.print(readMux1(4));
    Serial.print(" sw="); Serial.println(digitalRead(STICK1_SW) == LOW ? "down" : "up");
  }
}

/*
 * Autoino 자동 생성 스케치
 * 프로젝트 : mux-esp32
 * 보드     : 보드 1 · ESP32 DevKit V1 (arduino-esp32 코어)
 * 생성 시각: 2026-01-01T00:00:00+00:00
 *
 * 핀 배정 (Autoino 배선 기준)
 *   아날로그 멀티플렉서 (16채널) 1 · SIG → GPIO36 (아날로그 멀티플렉서 공통 신호)
 *   아날로그 멀티플렉서 (16채널) 1 · S0 → GPIO32 (채널 선택 비트 0)
 *   아날로그 멀티플렉서 (16채널) 1 · S1, S2, S3 → GND (쓰지 않는 선택선)
 *   가변저항 10 kΩ 1 · OUT → 아날로그 멀티플렉서 (16채널) 1 C0
 *   MQ-2 가스 센서 1 · AO → 아날로그 멀티플렉서 (16채널) 1 C1
 *
 * 필요한 라이브러리
 *   - 없음
 *
 * 이 코드는 배선을 확인하기 위한 동작 예시입니다. 실제 제품·라이브러리 버전에 맞게 확인하세요.
 */

// ---------- 핀 · 전역 변수 ----------
const uint8_t MUX1_SIG = 36;  // 아날로그 멀티플렉서 (16채널) 1 · SIG → GPIO36 (아날로그 멀티플렉서 공통 신호)
const uint8_t MUX1_S0 = 32;  // 아날로그 멀티플렉서 (16채널) 1 · S0 → GPIO32 (채널 선택 비트 0)
const uint8_t MUX1_SELECT[1] = {MUX1_S0};  // S0 부터. 나머지 선택선은 GND
unsigned long timer_pot1 = 0;
unsigned long timer_gas1 = 0;
// 아날로그 멀티플렉서 (16채널) 1: 아날로그 센서 2개를 채널로 나눠 읽습니다 (아래 read 함수).

// 간격(ms)마다 한 번 true 를 돌려주는 비차단 타이머
bool every(unsigned long &last, unsigned long intervalMs) {
  unsigned long now = millis();
  if (now - last < intervalMs) return false;
  last = now;
  return true;
}

// 아날로그 멀티플렉서 (16채널) 1: 채널(0–1)을 골라 SIG(GPIO36) 로 읽는다
int readMux1(uint8_t channel) {
  for (uint8_t i = 0; i < 1; i++) digitalWrite(MUX1_SELECT[i], (channel >> i) & 1);
  delayMicroseconds(10);  // 채널을 바꾼 뒤 신호가 자리 잡을 시간
  analogRead(MUX1_SIG);  // 첫 값은 버린다 (ADC 가 새 채널 전압으로 바뀌도록)
  return analogRead(MUX1_SIG);
}

void setup() {
  Serial.begin(115200);
  for (uint8_t i = 0; i < 1; i++) pinMode(MUX1_SELECT[i], OUTPUT);
  Serial.println("Autoino: autoino_board_1.ino start");
}

void loop() {
  // 가변저항 10 kΩ 1: 0.5초마다 아날로그 값 출력
  if (every(timer_pot1, 500)) { Serial.print("pot1: "); Serial.println(readMux1(0)); }
  // MQ-2 가스 센서 1: 0.5초마다 아날로그 값 출력
  if (every(timer_gas1, 500)) { Serial.print("gas1: "); Serial.println(readMux1(1)); }
}
